-- Vaubaan Gateway v5 — schema v1.
--
-- Spec: docs/spec/vaubaan-gateway.md §2 (domain), §3 (budget, requests, approvals),
-- §6 (encryption at rest, immutable audit), §8 (audit fields).
-- ADR:  docs/decisions/embedded-store-sqlite-and-migrations.md
--
-- Conventions (see the ADR for the rationale):
--   * ids are TEXT UUIDv7 generated by the application;
--   * every timestamp is an ISO-8601 UTC TEXT supplied by the application (never
--     CURRENT_TIMESTAMP, whose format differs between engines);
--   * enumerations of RiskId are rows, never JSON arrays; a CHECK forbids the
--     wildcard character so no sentinel can ever be persisted;
--   * booleans are INTEGER 0/1 with a CHECK;
--   * JSON TEXT is used only for opaque metadata and forensic snapshots that are
--     never read for authorization.
--
-- SQLite-specific spots are marked "-- sqlite:" so a Postgres port can grep them: the
-- STRICT table option and the RAISE(ABORT) syntax inside triggers. Everything else
-- (UPSERT, partial unique indexes, CHECK, foreign keys) is standard SQL that Postgres
-- accepts as written.
--
-- schema_migrations is created by the migration runner before this file runs.

------------------------------------------------------------------------------
-- Instance
------------------------------------------------------------------------------

CREATE TABLE instance_config (
  key          TEXT    NOT NULL PRIMARY KEY,
  value        TEXT,                     -- clear value (JSON-encoded by the caller)
  secret_blob  BLOB,                     -- AEAD blob, associated data 'instance_config:<key>'
  key_version  INTEGER,                  -- master-key version used to seal secret_blob
  updated_at   TEXT    NOT NULL,
  CHECK ((value IS NULL) <> (secret_blob IS NULL)),
  CHECK (secret_blob IS NULL OR key_version IS NOT NULL)
) STRICT; -- sqlite: STRICT

------------------------------------------------------------------------------
-- Identities
------------------------------------------------------------------------------

CREATE TABLE users (
  id            TEXT NOT NULL PRIMARY KEY,
  subject       TEXT NOT NULL UNIQUE,    -- stable IdP subject
  email         TEXT NOT NULL,
  display_name  TEXT,
  status        TEXT NOT NULL CHECK (status IN ('active', 'removed')),
  created_at    TEXT NOT NULL,
  last_login_at TEXT,
  removed_at    TEXT
) STRICT; -- sqlite: STRICT

CREATE INDEX users_email ON users (email);

CREATE TABLE groups (
  id          TEXT NOT NULL PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  source      TEXT NOT NULL CHECK (source IN ('idp', 'local')),
  created_at  TEXT NOT NULL
) STRICT; -- sqlite: STRICT

CREATE TABLE group_members (
  group_id  TEXT NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
  user_id   TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  added_at  TEXT NOT NULL,
  PRIMARY KEY (group_id, user_id)
) STRICT; -- sqlite: STRICT

CREATE INDEX group_members_user ON group_members (user_id);

------------------------------------------------------------------------------
-- Delegations (management surface over OAuth)
------------------------------------------------------------------------------

CREATE TABLE oauth_clients (
  id                  TEXT NOT NULL PRIMARY KEY,
  client_id           TEXT NOT NULL UNIQUE,
  client_secret_hash  TEXT,                -- NULL for public (PKCE-only) clients
  name                TEXT NOT NULL,
  created_at          TEXT NOT NULL
) STRICT; -- sqlite: STRICT

CREATE TABLE oauth_client_redirect_uris (
  client_id  TEXT NOT NULL REFERENCES oauth_clients (id) ON DELETE CASCADE,
  uri        TEXT NOT NULL,
  PRIMARY KEY (client_id, uri)
) STRICT; -- sqlite: STRICT

CREATE TABLE delegations (
  id          TEXT NOT NULL PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users (id),
  client_id   TEXT NOT NULL REFERENCES oauth_clients (id),
  scope       TEXT NOT NULL,              -- management scope string granted at consent
  status      TEXT NOT NULL CHECK (status IN ('active', 'revoked')),
  created_at  TEXT NOT NULL,
  revoked_at  TEXT
) STRICT; -- sqlite: STRICT

CREATE INDEX delegations_user ON delegations (user_id);

CREATE TABLE oauth_codes (
  id                     TEXT NOT NULL PRIMARY KEY,
  code_hash              TEXT NOT NULL UNIQUE,
  delegation_id          TEXT NOT NULL REFERENCES delegations (id) ON DELETE CASCADE,
  redirect_uri           TEXT NOT NULL,
  code_challenge         TEXT NOT NULL,
  code_challenge_method  TEXT NOT NULL CHECK (code_challenge_method IN ('S256')),
  created_at             TEXT NOT NULL,
  expires_at             TEXT NOT NULL,
  consumed_at            TEXT
) STRICT; -- sqlite: STRICT

CREATE TABLE oauth_refresh_tokens (
  id             TEXT NOT NULL PRIMARY KEY,
  delegation_id  TEXT NOT NULL REFERENCES delegations (id) ON DELETE CASCADE,
  token_hash     TEXT NOT NULL UNIQUE,
  created_at     TEXT NOT NULL,
  expires_at     TEXT NOT NULL,
  revoked_at     TEXT,
  replaced_by_id TEXT REFERENCES oauth_refresh_tokens (id)
) STRICT; -- sqlite: STRICT

CREATE INDEX oauth_refresh_tokens_delegation ON oauth_refresh_tokens (delegation_id);

CREATE TABLE oauth_access_tokens (
  id             TEXT NOT NULL PRIMARY KEY,
  delegation_id  TEXT NOT NULL REFERENCES delegations (id) ON DELETE CASCADE,
  token_hash     TEXT NOT NULL UNIQUE,
  created_at     TEXT NOT NULL,
  expires_at     TEXT NOT NULL,
  revoked_at     TEXT
) STRICT; -- sqlite: STRICT

CREATE INDEX oauth_access_tokens_delegation ON oauth_access_tokens (delegation_id);

------------------------------------------------------------------------------
-- Connections, resources, shares
------------------------------------------------------------------------------

CREATE TABLE connections (
  id                     TEXT    NOT NULL PRIMARY KEY,
  provider               TEXT    NOT NULL,     -- plugin id; validated against the registry by the app
  owner_kind             TEXT    NOT NULL CHECK (owner_kind IN ('user', 'group')),
  owner_user_id          TEXT    REFERENCES users (id),
  owner_group_id         TEXT    REFERENCES groups (id),
  display_name           TEXT    NOT NULL,
  status                 TEXT    NOT NULL CHECK (status IN ('active', 'expired', 'revoked', 'unowned')),
  credential_blob        BLOB,                 -- AEAD blob, associated data = connection id
  key_version            INTEGER,
  credential_expires_at  TEXT,
  metadata_json          TEXT,                 -- opaque plugin metadata (team id, installation id…)
  created_at             TEXT    NOT NULL,
  updated_at             TEXT    NOT NULL,
  revoked_at             TEXT,
  CHECK (
    (owner_kind = 'user'  AND owner_user_id IS NOT NULL AND owner_group_id IS NULL) OR
    (owner_kind = 'group' AND owner_group_id IS NOT NULL AND owner_user_id IS NULL)
  ),
  CHECK (credential_blob IS NULL OR key_version IS NOT NULL)
) STRICT; -- sqlite: STRICT

CREATE INDEX connections_owner_user  ON connections (owner_user_id);
CREATE INDEX connections_owner_group ON connections (owner_group_id);
CREATE INDEX connections_provider    ON connections (provider);

CREATE TABLE connection_resources (
  id             TEXT NOT NULL PRIMARY KEY,
  connection_id  TEXT NOT NULL REFERENCES connections (id) ON DELETE CASCADE,
  ref            TEXT NOT NULL,                -- what the agent cites in its arguments
  env            TEXT,                         -- environment label set by the owner (prod, staging…)
  display_name   TEXT NOT NULL,
  discovered_at  TEXT NOT NULL,
  UNIQUE (connection_id, ref)
) STRICT; -- sqlite: STRICT

CREATE TABLE shares (
  id                  TEXT NOT NULL PRIMARY KEY,
  connection_id       TEXT NOT NULL REFERENCES connections (id) ON DELETE CASCADE,
  target_kind         TEXT NOT NULL CHECK (target_kind IN ('user', 'group')),
  target_user_id      TEXT REFERENCES users (id),
  target_group_id     TEXT REFERENCES groups (id),
  status              TEXT NOT NULL CHECK (status IN ('active', 'revoked')),
  created_by_user_id  TEXT NOT NULL REFERENCES users (id),
  created_at          TEXT NOT NULL,
  revoked_at          TEXT,
  CHECK (
    (target_kind = 'user'  AND target_user_id IS NOT NULL AND target_group_id IS NULL) OR
    (target_kind = 'group' AND target_group_id IS NOT NULL AND target_user_id IS NULL)
  )
) STRICT; -- sqlite: STRICT

CREATE INDEX shares_connection   ON shares (connection_id);
CREATE INDEX shares_target_user  ON shares (target_user_id);
CREATE INDEX shares_target_group ON shares (target_group_id);

-- Restriction = explicit enumeration of RiskId. One row per risk; no wildcard can be stored.
CREATE TABLE share_restrictions (
  share_id  TEXT NOT NULL REFERENCES shares (id) ON DELETE CASCADE,
  risk_id   TEXT NOT NULL CHECK (risk_id <> '' AND risk_id NOT LIKE '%*%'),
  PRIMARY KEY (share_id, risk_id)
) STRICT; -- sqlite: STRICT

------------------------------------------------------------------------------
-- Missions
------------------------------------------------------------------------------

CREATE TABLE missions (
  id               TEXT    NOT NULL PRIMARY KEY,
  name             TEXT    NOT NULL,
  creator_user_id  TEXT    NOT NULL REFERENCES users (id),
  -- 'exhausted' is per risk and computed from counters, never stored.
  status           TEXT    NOT NULL CHECK (status IN ('active', 'expired', 'orphaned', 'revoked')),
  period_anchor    TEXT    NOT NULL,            -- start of the first period
  period_seconds   INTEGER CHECK (period_seconds IS NULL OR period_seconds > 0), -- NULL = one-off
  expires_at       TEXT,
  delegation_id    TEXT    REFERENCES delegations (id), -- set when issued through the management door
  created_at       TEXT    NOT NULL,
  updated_at       TEXT    NOT NULL,
  closed_at        TEXT
) STRICT; -- sqlite: STRICT

CREATE INDEX missions_creator ON missions (creator_user_id);

CREATE TABLE mission_connections (
  mission_id      TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  connection_id   TEXT NOT NULL REFERENCES connections (id),
  resource_scope  TEXT NOT NULL CHECK (resource_scope IN ('all', 'selected')),
  PRIMARY KEY (mission_id, connection_id)
) STRICT; -- sqlite: STRICT

CREATE INDEX mission_connections_connection ON mission_connections (connection_id);

-- Resource selection, one row per selected resource (used when resource_scope = 'selected').
CREATE TABLE mission_resources (
  mission_id     TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  connection_id  TEXT NOT NULL,
  resource_id    TEXT NOT NULL REFERENCES connection_resources (id) ON DELETE CASCADE,
  PRIMARY KEY (mission_id, resource_id),
  FOREIGN KEY (mission_id, connection_id) REFERENCES mission_connections (mission_id, connection_id) ON DELETE CASCADE
) STRICT; -- sqlite: STRICT

-- Policy = RiskId -> (quota, rate limit, gate). One row per accepted risk; every accepted risk
-- carries a budget (the absence of a quota is not allowed, spec §3.2).
CREATE TABLE mission_policy (
  mission_id           TEXT    NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  risk_id              TEXT    NOT NULL CHECK (risk_id <> '' AND risk_id NOT LIKE '%*%'),
  quota                INTEGER NOT NULL CHECK (quota >= 0),
  rate_limit           INTEGER NOT NULL CHECK (rate_limit >= 0),
  rate_window_seconds  INTEGER NOT NULL CHECK (rate_window_seconds > 0),
  gate                 TEXT    NOT NULL CHECK (gate IN ('auto', 'approval')),
  PRIMARY KEY (mission_id, risk_id)
) STRICT; -- sqlite: STRICT

CREATE TABLE mission_tokens (
  id          TEXT NOT NULL PRIMARY KEY,
  mission_id  TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  prefix      TEXT NOT NULL UNIQUE,           -- public lookup key, safe to log
  hash        TEXT NOT NULL,                  -- hash of the secret part
  hash_alg    TEXT NOT NULL,                  -- e.g. 'argon2id', 'sha256'
  status      TEXT NOT NULL CHECK (status IN ('active', 'rotated', 'revoked')),
  created_at  TEXT NOT NULL,
  retired_at  TEXT
) STRICT; -- sqlite: STRICT

-- One active token per mission; rotation retires the previous row.
CREATE UNIQUE INDEX mission_tokens_one_active ON mission_tokens (mission_id) WHERE status = 'active';

------------------------------------------------------------------------------
-- Sessions, counters, events
------------------------------------------------------------------------------

CREATE TABLE sessions (
  id          TEXT NOT NULL PRIMARY KEY,
  mission_id  TEXT NOT NULL UNIQUE REFERENCES missions (id) ON DELETE CASCADE,
  created_at  TEXT NOT NULL
) STRICT; -- sqlite: STRICT

-- Durable quota counters: a restart never forgets a consumed credit.
CREATE TABLE session_counters (
  session_id    TEXT    NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
  risk_id       TEXT    NOT NULL,
  period_start  TEXT    NOT NULL,
  consumed      INTEGER NOT NULL DEFAULT 0 CHECK (consumed >= 0),
  PRIMARY KEY (session_id, risk_id, period_start)
) STRICT; -- sqlite: STRICT

CREATE TABLE events (
  id             TEXT NOT NULL PRIMARY KEY,
  session_id     TEXT NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
  ts             TEXT NOT NULL,
  kind           TEXT NOT NULL,              -- allowed-call, refused-call, request, extension, reset, …
  risk_id        TEXT,
  actor_user_id  TEXT REFERENCES users (id),
  details_json   TEXT
) STRICT; -- sqlite: STRICT

CREATE INDEX events_session_ts ON events (session_id, ts);

------------------------------------------------------------------------------
-- Requests and approvals
------------------------------------------------------------------------------

CREATE TABLE requests (
  id                  TEXT NOT NULL PRIMARY KEY,
  mission_id          TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  session_id          TEXT REFERENCES sessions (id) ON DELETE SET NULL,
  kind                TEXT NOT NULL CHECK (kind IN ('claim', 'approval')),
  state               TEXT NOT NULL CHECK (state IN ('open', 'granted', 'refused', 'expired')),
  risk_id             TEXT NOT NULL,
  tool                TEXT,                   -- approval requests only
  fingerprint         TEXT,                   -- sha256 of the canonical arguments, approval only
  args_blob           BLOB,                   -- AEAD blob, associated data = request id; erased on decision/expiry
  key_version         INTEGER,
  created_at          TEXT NOT NULL,
  expires_at          TEXT NOT NULL,
  decided_at          TEXT,
  decided_by_user_id  TEXT REFERENCES users (id),
  decision_json       TEXT,                   -- creator's answer (extension amount, gate opened…)
  CHECK (kind = 'claim' OR (tool IS NOT NULL AND fingerprint IS NOT NULL)),
  CHECK (args_blob IS NULL OR key_version IS NOT NULL),
  CHECK (state <> 'open' OR decided_at IS NULL)
) STRICT; -- sqlite: STRICT

CREATE INDEX requests_mission_state ON requests (mission_id, state);
CREATE INDEX requests_open_expiry   ON requests (expires_at) WHERE state = 'open';

CREATE TABLE approvals (
  id           TEXT NOT NULL PRIMARY KEY,
  mission_id   TEXT NOT NULL REFERENCES missions (id) ON DELETE CASCADE,
  request_id   TEXT NOT NULL UNIQUE REFERENCES requests (id),
  risk_id      TEXT NOT NULL,
  fingerprint  TEXT NOT NULL,
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  consumed_at  TEXT
) STRICT; -- sqlite: STRICT

CREATE INDEX approvals_lookup ON approvals (mission_id, risk_id, fingerprint) WHERE consumed_at IS NULL;

------------------------------------------------------------------------------
-- Audit (append-only)
------------------------------------------------------------------------------

CREATE TABLE audit (
  id                   TEXT    NOT NULL PRIMARY KEY,
  ts                   TEXT    NOT NULL,
  kind                 TEXT    NOT NULL CHECK (kind IN ('call', 'admin')),
  -- call entries
  mission_id           TEXT,
  session_id           TEXT,
  connection_id        TEXT,
  resource_ref         TEXT,
  tool                 TEXT,
  arguments_hash       TEXT,
  slices_json          TEXT,                  -- forensic snapshot of the slices executed
  decision             TEXT    CHECK (decision IS NULL OR decision IN ('allowed', 'refused')),
  refusal_code         TEXT,
  refusal_reason       TEXT,
  approval_id          TEXT,
  agent_label          TEXT,
  upstream_latency_ms  INTEGER,
  upstream_error       TEXT,                  -- provider failure after an allow; the decision stays 'allowed'
  client_ip            TEXT,
  client_user_agent    TEXT,
  -- administrative entries (gateway-core AdminAuditEntry)
  user_id              TEXT,
  act                  TEXT,
  object_type          TEXT,
  object_id            TEXT,
  before_json          TEXT,                  -- previous state when meaningful, never a secret
  after_json           TEXT,
  delegated_client_id  TEXT,
  CHECK (kind <> 'call'  OR (mission_id IS NOT NULL AND tool IS NOT NULL AND arguments_hash IS NOT NULL AND decision IS NOT NULL)),
  CHECK (kind <> 'admin' OR (user_id IS NOT NULL AND act IS NOT NULL AND object_type IS NOT NULL AND object_id IS NOT NULL))
) STRICT; -- sqlite: STRICT

CREATE INDEX audit_ts         ON audit (ts);
CREATE INDEX audit_mission_ts ON audit (mission_id, ts);

-- Per-risk rows of a call entry: the accepted-risks snapshot, the risks touched, and the
-- remaining budget after the call. Rows, not JSON, so the counters-vs-audit structural
-- check is a plain join.
CREATE TABLE audit_risks (
  audit_id   TEXT    NOT NULL REFERENCES audit (id),
  risk_id    TEXT    NOT NULL,
  accepted   INTEGER NOT NULL CHECK (accepted IN (0, 1)),
  touched    INTEGER NOT NULL CHECK (touched IN (0, 1)),
  remaining  INTEGER,
  PRIMARY KEY (audit_id, risk_id)
) STRICT; -- sqlite: STRICT

-- The retention purge opens a "window" by inserting the single row of this table inside
-- its transaction; the delete triggers below let rows older than the cutoff go only while
-- the window is open. Any other delete, and every update, aborts.
CREATE TABLE audit_purge_guard (
  id      INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
  cutoff  TEXT    NOT NULL
) STRICT; -- sqlite: STRICT

CREATE TRIGGER audit_no_update
BEFORE UPDATE ON audit
BEGIN
  SELECT RAISE(ABORT, 'audit is append-only'); -- sqlite: RAISE syntax
END;

CREATE TRIGGER audit_no_delete
BEFORE DELETE ON audit
WHEN NOT EXISTS (SELECT 1 FROM audit_purge_guard WHERE OLD.ts < cutoff)
BEGIN
  SELECT RAISE(ABORT, 'audit is append-only; use the retention purge'); -- sqlite: RAISE syntax
END;

CREATE TRIGGER audit_risks_no_update
BEFORE UPDATE ON audit_risks
BEGIN
  SELECT RAISE(ABORT, 'audit is append-only'); -- sqlite: RAISE syntax
END;

CREATE TRIGGER audit_risks_no_delete
BEFORE DELETE ON audit_risks
WHEN NOT EXISTS (SELECT 1 FROM audit_purge_guard)
BEGIN
  SELECT RAISE(ABORT, 'audit is append-only; use the retention purge'); -- sqlite: RAISE syntax
END;
